package com.mineclone;

import com.mineclone.game.*;
import com.mineclone.world.*;
import com.mineclone.world.damage.*;
import com.mineclone.world.effect.*;
import com.mineclone.world.entity.*;
import com.mineclone.save.*;
import com.mineclone.sim.*;
import java.util.*;

/** Survival regression scenarios: resource cost, effect timelines, environmental causes and death conservation. */
final class SurvivalRulesTests {
    static void runAll(TestMain.Runner r){
        r.run("a 21-minute active survival day costs two or three cooked portions",SurvivalRulesTests::activeDay);
        r.run("non-flying mobs drown after their air expires and recover on the surface",SurvivalRulesTests::mobAir);
        r.run("peaceful removes hostiles immediately and stays empty for ten night minutes",SurvivalRulesTests::peaceful);
        r.run("lightning damages only participants inside its typed two-block radius",SurvivalRulesTests::lightning);
        r.run("exhaustion spends saturation before hunger and idle time does not drain food",SurvivalRulesTests::exhaustion);
        r.run("fast and slow regeneration spend food and obey difficulty and the world rule",SurvivalRulesTests::regeneration);
        r.run("air depletes before drowning and refills without armor protection",SurvivalRulesTests::air);
        r.run("effects stack by max, poison cannot kill and unknown effects survive saving",SurvivalRulesTests::effects);
        r.run("food needs held time and cancels on damage slot changes and release",SurvivalRulesTests::eating);
        r.run("fire lava cactus opaque heads water and void use independent typed pulses",SurvivalRulesTests::hazards);
        r.run("death conserves inventory equipment cursor and ten-minute item lifetime",SurvivalRulesTests::death);
        r.run("every damage type has a death cause and obstructed beds refuse respawn",SurvivalRulesTests::respawn);
        r.run("world rules round trip and damaged or future rules are refused",SurvivalRulesTests::rules);
        r.run("positioned damage directions rotate with the camera and expire",SurvivalRulesTests::direction);
    }
    static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
    static void near(float value,float expected){check(Math.abs(value-expected)<.001,"value "+value+" expected "+expected);}
    static void activeDay(){var p=new Player();var food=com.mineclone.item.Items.get().require("cooked_beef").food;var random=new Random(123);int portions=0;
        for(int second=0;second<1260;second++){p.exhaust(.135f);if(second%5==0)p.exhaust(.05f);if(second%2==0)p.exhaust(.005f);if(second%10==0)p.exhaust(.1f);
            if(second==100||second==300||second==500||second==700)p.damage(DamageSource.of(DamageType.FALL),2);
            p.tickHunger(1,true);p.tickEffects(1);p.tickRegeneration(1,true);if(p.hunger<=12){p.eat(food,random);portions++;}}
        check(portions>=2&&portions<=3,"active day food portions "+portions);check(p.health>0,"day starvation");}
    static void mobAir(){var w=FarmingTests.blank();var m=new Mob(MobType.COW,6.5f,41,6.5f,new Random(1));w.setBlock(6,42,6,BlockType.WATER);float health=m.health;m.tickAir(w,15);near(m.health,health);m.tickAir(w,2);near(m.health,health-4);w.setBlock(6,42,6,BlockType.AIR);m.tickAir(w,3);near(m.air,300);}
    static void peaceful(){var w=FarmingTests.blank();w.rules=w.rules.difficulty(Difficulty.PEACEFUL);var entities=new EntityStore();var zombie=new Mob(MobType.ZOMBIE,6.5f,41,6.5f,new Random(1));entities.mobs.add(zombie);var clock=new WorldClock();var player=new Player();player.position.set(6,41,6);var people=new Participants();people.put(new LocalParticipant(player,()->1));var session=new WorldSession(w,clock,new MobSpawner(1),entities,people,new WorldSession.Host(){public org.joml.Vector3f mobFocus(){return player.position;}},WorldEvents.NONE);for(int i=0;i<600;i++){clock.advance(1);session.tickMobs(1);check(entities.mobs.stream().noneMatch(m->m.type.hostile),"peaceful spawned a hostile at "+i);}
        for(var difficulty:Difficulty.values()){int elites=0;for(int i=0;i<4096;i++)if(MobTactics.eliteFor(17,i,true,difficulty.eliteChance)!=MobTactics.Elite.NONE)elites++;if(difficulty==Difficulty.PEACEFUL)check(elites==0,"peaceful elite");else check(elites>0,"difficulty elite");}}
    static void lightning(){var w=FarmingTests.blank();var people=new Participants();var close=new Player();close.position.set(6,41,6);var far=new Player();far.position.set(9,41,6);people.put(new LocalParticipant(close,()->0));var distant=new LocalParticipant(far,()->1);people.put(distant);var session=new WorldSession(w,new WorldClock(),new MobSpawner(1),new EntityStore(),people,new WorldSession.Host(){public org.joml.Vector3f mobFocus(){return close.position;}},WorldEvents.NONE);session.lightning(6,41,6);near(close.health,15);near(far.health,20);check(close.lastDamageSource.type()==DamageType.LIGHTNING,"lightning cause");}
    static void exhaustion(){var p=new Player();p.exhaust(24);near(p.saturation,0);near(p.hunger,19);near(p.exhaustion,0);p.tickHunger(1200,true);near(p.hunger,19);p.setGameMode(GameMode.CREATIVE);p.exhaust(100);near(p.hunger,20);}
    static void regeneration(){var p=new Player();p.health=10;p.tickRegeneration(.5f,true);near(p.health,11);near(p.exhaustion,2);near(p.saturation,4);p.saturation=0;p.exhaustion=0;p.tickRegeneration(4,true);near(p.health,12);near(p.hunger,19);p.rules=p.rules.set("naturalRegeneration",false);p.tickRegeneration(100,true);near(p.health,12);p.rules=p.rules.difficulty(Difficulty.PEACEFUL);p.tickRegeneration(4,true);near(p.health,14);p.rules=p.rules.difficulty(Difficulty.EASY);p.health=20;p.hunger=0;p.tickHunger(100,true);near(p.health,10);p.rules=p.rules.difficulty(Difficulty.HARD);p.tickHunger(100,true);near(p.health,0);}
    static void air(){var p=new Player();p.eyeInWater=true;p.tickAir(15);near(p.air,0);near(p.health,20);p.tickAir(2);near(p.health,16);p.eyeInWater=false;p.tickAir(3);near(p.air,300);p.eyeInWater=true;p.setGameMode(GameMode.CREATIVE);p.tickAir(60);near(p.health,20);near(p.air,300);}
    static void effects(){var p=new Player();p.effects.apply(StatusEffect.POISON,3);p.effects.apply(StatusEffect.POISON,1,2,null,false);near(p.effects.remaining(StatusEffect.POISON),3);p.health=2;p.tickEffects(20);near(p.health,1);check(!p.effects.active(StatusEffect.POISON),"expired poison");p.effects.apply(StatusEffect.REGENERATION,3);p.tickEffects(3);near(p.health,4);p.effects.apply(StatusEffect.SPEED,2);p.effects.apply(StatusEffect.SLOWNESS,2);near(p.effects.movementMultiplier(),1.02f);p.effects.restore(List.of(new PlayerRecord.Effect("future:test",999,4),new PlayerRecord.Effect("mineclone:speed",40,0)));p.tickEffects(1);check(p.effects.snapshot().stream().anyMatch(e->e.id().equals("future:test")&&e.remainingTicks()==999),"unknown effect lost");check(p.effects.snapshot().stream().anyMatch(e->e.id().endsWith("speed")&&e.remainingTicks()==20),"remaining effect ticks");}
    static void eating(){var animation=new com.mineclone.render.PlayerAnimation();for(float progress:new float[]{.1f,.5f,.9f}){animation.setEating(progress);var palm=com.mineclone.render.PlayerRenderer.handPose(new org.joml.Vector3f(),0,animation.pose()).transformPosition(new org.joml.Vector3f());check(palm.distance(0,1.6f,-.3f)<.35f,"food hand is away from mouth");}var p=new Player();p.hunger=10;var e=new Eating();var stack=ItemStack.of("bread",3);var random=new Random(0);e.update(p,stack,0,true,1,random);check(stack.count==3,"early consume");e.update(p,stack,0,false,1,random);e.update(p,stack,0,true,1,random);check(stack.count==3,"release not cancelled");p.damage(DamageSource.of(DamageType.FALL),1);e.update(p,stack,0,true,.7f,random);check(stack.count==3,"damage consumed");e.update(p,stack,0,true,1,random);e.update(p,stack,1,true,.7f,random);check(stack.count==3,"slot consumed");e.update(p,stack,1,true,1,random);check(stack.count==2&&p.effects.active(StatusEffect.WELL_FED),"bread completion/effect");p.hunger=20;e.update(p,stack,1,true,2,random);check(stack.count==2,"full consumed bread");var apple=ItemStack.of("apple",2);e.update(p,apple,0,true,1.6f,random);check(apple.count==1,"full apple refused");}
    static void hazards(){var w=FarmingTests.blank();var p=new Player();p.position.set(6.5f,40,6.5f);var h=new EnvironmentalHazards();w.setBlock(6,40,6,BlockType.FIRE);h.tick(p,w,1);near(p.health,19);check(p.lastDamageSource.type()==DamageType.FIRE,"fire cause");p.inWater=true;w.setBlock(6,40,6,BlockType.AIR);h.tick(p,w,1);near(p.health,19);check(!h.burning(),"water not extinguishing");p.inWater=false;w.setBlock(6,40,6,BlockType.LAVA);h.tick(p,w,1);near(p.health,15);p.effects.apply(StatusEffect.FIRE_RESISTANCE,10);h.tick(p,w,1);near(p.health,15);w.setBlock(6,40,6,BlockType.CACTUS);h.tick(p,w,.5f);near(p.health,14);w.setBlock(6,41,6,BlockType.STONE);h.tick(p,w,.5f);check(p.lastDamageSource.type()==DamageType.SUFFOCATE,"suffocation cause");p.position.y=-18;h.tick(p,w,1);check(p.lastDamageSource.type()==DamageType.VOID,"void cause");}
    static void death(){var inv=new ItemStack[Inventory.SIZE];inv[0]=ItemStack.of("bread",31);inv[1]=ItemStack.of("iron_pickaxe");inv[1].setDamage(77);var eq=new ItemStack[]{ItemStack.of("iron_helmet"),null,null,null,ItemStack.of("torch",12)};var record=PlayerRecord.builder().inventory(inv).equipment(eq).pending(new ItemStack[]{ItemStack.of("diamond",3)}).pose(3,42,5,0,0,0).build();var death=DeathDrops.prepare(record,false);check(death.items().stream().mapToInt(i->i.stack.count).sum()==48,"death conservation");check(Arrays.stream(death.record().inventory()).allMatch(Objects::isNull)&&Arrays.stream(death.record().equipment()).allMatch(Objects::isNull)&&death.record().pending().length==0,"death clear");check(death.items().stream().filter(i->i.stack.item.id.path().equals("iron_pickaxe")).findFirst().orElseThrow().stack.damage()==77,"components");for(var item:death.items()){item.age=599;check(!item.expired(),"expired before 10 minutes");item.age=600;check(item.expired(),"lifetime unbounded");}check(DeathDrops.prepare(record,true).items().isEmpty(),"keep inventory dropped");check(record.inventory()[0].count==31,"snapshot mutated");}
    static void respawn(){for(var type:DamageType.values())check(!DeathMessage.text(DamageSource.of(type)).isBlank(),"missing cause "+type);var w=FarmingTests.blank();var spawn=new PlayerRecord.Spawn(6.5,41,6.5);w.setBlock(6,40,6,BlockType.BEDROLL);check(SleepRules.validSpawn(w,spawn),"clear bed");w.setBlock(6,42,6,BlockType.STONE);check(!SleepRules.validSpawn(w,spawn),"covered bed");w.setBlock(6,42,6,BlockType.AIR);w.setBlock(6,41,6,BlockType.LAVA);check(!SleepRules.validSpawn(w,spawn),"lava bed");w.setBlock(6,41,6,BlockType.AIR);w.setBlock(6,40,6,BlockType.AIR);check(!SleepRules.validSpawn(w,spawn),"lost bed");}
    static void rules(){check(WorldRules.decode(null).equals(WorldRules.LEGACY),"legacy rules");for(var d:Difficulty.values()){var rules=new WorldRules(d,false,false,false,false);check(WorldRules.decode(rules.encode()).equals(rules),"rules roundtrip");}for(byte[] body:new byte[][]{new byte[]{9},new byte[]{1,0},new byte[80]})try{WorldRules.decode(body);throw new AssertionError("invalid rules accepted");}catch(IllegalArgumentException expected){}}
    static void direction(){var h=new HurtIndicator();float[][] directions={{0,-2,0},{2,0,(float)Math.PI/2},{0,2,(float)Math.PI},{-2,0,(float)-Math.PI/2}};for(var d:directions){h.hit(DamageSource.byMob(DamageType.MELEE,MobType.ZOMBIE,d[0],0,d[1],1),0,0);near((float)Math.atan2(Math.sin(h.angle(0)-d[2]),Math.cos(h.angle(0)-d[2])),0);}h.hit(DamageSource.byMob(DamageType.MELEE,MobType.ZOMBIE,-2,0,2,1),0,0);near(h.angle(0),(float)(-Math.PI*.75));near(h.angle((float)(Math.PI/2)),(float)(Math.PI*.75));h.tick(1.3f);near(h.alpha(),0);h.hit(DamageSource.of(DamageType.FALL),0,0);near(h.alpha(),0);}
}
